<script lang="ts">
  import { kubernetesAccessModeLabel, type KubernetesAccessMode } from './resourceWorkflow';
  export let resourceName=''; export let resourceStatus='active'; export let accessMode: KubernetesAccessMode='direct'; export let connectionOverride=false; export let server=''; export let mcpServerName=''; export let credentialConfigured=false; export let scopeSummary=''; export let labelsConfigured=false; export let testBusy=false; export let testStatus=''; export let testMessage=''; export let testError=''; export let testLatency:number|undefined; export let onSubmit=()=>{};
  const tools=['kubernetes_cluster_info','kubernetes_api_resources','kubernetes_namespaces','kubernetes_nodes','kubernetes_pods','kubernetes_workloads','kubernetes_services','kubernetes_configmaps','kubernetes_ingresses','kubernetes_events','kubernetes_pod_logs','kubernetes_resource_get','kubernetes_health'];
</script>
<p class="resource-add-description">确认 Kubernetes 接入路径。工具集仅提供只读集群信息、资源、日志和健康检查。</p>
<form id="kubernetes-review-form" class="provider-summary docker-summary" on:submit|preventDefault={onSubmit}><div><span>Kubernetes 资源</span><strong>{resourceName}</strong><small>{resourceStatus === 'active' ? '已启用' : '已停用'} · {scopeSummary}</small></div><div><span>接入方式</span><strong>{kubernetesAccessModeLabel(accessMode)}</strong><small>{accessMode === 'agent' ? mcpServerName : server || '默认 kubeconfig'}</small></div><div><span>连接凭据</span><strong>{accessMode === 'agent' && !connectionOverride ? '由 MCPServer 管理' : credentialConfigured ? '已配置' : '使用环境或默认配置'}</strong></div><div><span>资源属性</span><strong>{labelsConfigured ? '已配置标签' : '未配置标签'}</strong></div><div class="docker-tool-summary"><span>可用只读工具（{tools.length}）</span><div>{#each tools as tool}<code>{tool}</code>{/each}</div></div><div class="provider-test-summary"><span>连接核验</span>{#if testBusy}<strong>正在测试连接...</strong>{:else if testStatus === 'succeeded'}<strong class="success">连接正常 · {testLatency ?? 0} ms</strong><small>{testMessage}</small>{:else if testError}<strong class="failed">连接失败</strong><small>{testError}</small>{:else}<strong>尚未核验</strong><small>进入此步骤后自动执行连接测试。</small>{/if}</div></form>
